      OBJECT_CONSENSUS_ALPHA="0.2"
    fi
    ;;
  grad_tracking|gradient_tracking|riemannian_gradient_tracking)
    if [[ -z "${OBJECT_CONSENSUS_ALPHA}" ]]; then
      OBJECT_CONSENSUS_ALPHA="0.05"
    fi
    ;;
  exact_diffusion|riemannian_exact_diffusion|riemannian_exact)
