    "${OBJECT_LOCAL_OBJECTIVE}" "${OBJECT_CONSENSUS_MODE}" \
    "${OBJECT_CONSENSUS_ALPHA:-<default>}"
  printf '%q ' "${cmd[@]}"
  printf '\n'
  exit 0
